49: func (s *ImageSigner) Sign(ro *options.RootOptions, report platform.ExportReport, secretLocation string, annotations, cosignRepositories, cosignDockerMediaTypes map[string]interface{}) error {
50: 	cosignSecrets, err := findCosignSecrets(secretLocation)
51: 	if err != nil {
52: 		return errors.Errorf("no keys found for cosign signing: %v\n", err)
53: 	}
54: 
55: 	if len(cosignSecrets) == 0 {
56: 		return errors.New("no keys found for cosign signing")
57: 	}
58: 
59: 	if len(report.Image.Tags) == 0 {
60: 		return errors.New("no image found in report to sign")
61: 	}
62: 
63: 	refImage := report.Image.Tags[0]
64: 
65: 	for _, cosignSecret := range cosignSecrets {
66: 		if err := s.sign(ro, refImage, secretLocation, cosignSecret, annotations, cosignRepositories, cosignDockerMediaTypes); err != nil {
67: 			return err
68: 		}
69: 	}
70: 
71: 	return nil
72: }
