74: func (s *ImageSigner) sign(ro *options.RootOptions, refImage, secretLocation, cosignSecret string, annotations, cosignRepositories, cosignDockerMediaTypes map[string]interface{}) error {
75: 	cosignKeyFile := fmt.Sprintf("%s/%s/cosign.key", secretLocation, cosignSecret)
76: 	cosignPasswordFile := fmt.Sprintf("%s/%s/cosign.password", secretLocation, cosignSecret)
77: 
78: 	ko := options.KeyOpts{KeyRef: cosignKeyFile, PassFunc: func(bool) ([]byte, error) {
79: 		content, err := ioutil.ReadFile(cosignPasswordFile)
80: 		// When password file is not available, default empty password is used
81: 		if err != nil {
82: 			return []byte(""), nil
83: 		}
84: 
85: 		return content, nil
86: 	}}
87: 
88: 	if cosignRepository, ok := cosignRepositories[cosignSecret]; ok {
89: 		if err := os.Setenv(cosignutil.CosignRepositoryEnv, fmt.Sprintf("%s", cosignRepository)); err != nil {
90: 			return errors.Errorf("failed setting %s env variable: %v", cosignutil.CosignRepositoryEnv, err)
91: 		}
92: 		defer os.Unsetenv(cosignutil.CosignRepositoryEnv)
93: 	}
94: 
95: 	if cosignDockerMediaType, ok := cosignDockerMediaTypes[cosignSecret]; ok {
96: 		if err := os.Setenv(cosignutil.CosignDockerMediaTypesEnv, fmt.Sprintf("%s", cosignDockerMediaType)); err != nil {
97: 			return errors.Errorf("failed setting COSIGN_DOCKER_MEDIA_TYPES env variable: %v", err)
98: 		}
99: 		defer os.Unsetenv(cosignutil.CosignDockerMediaTypesEnv)
100: 	}
101: 
102: 	var cosignAnnotations []string
103: 	for key, value := range annotations {
104: 		cosignAnnotations = append(cosignAnnotations, fmt.Sprintf("%s=%s", key, value))
105: 	}
106: 
107: 	signOptions := options.SignOptions{
108: 		Registry: options.RegistryOptions{KubernetesKeychain: true},
109: 		AnnotationOptions: options.AnnotationOptions{
110: 			Annotations: cosignAnnotations,
111: 		},
112: 		Upload:     true,
113: 		Recursive:  false,
114: 		TlogUpload: false,
115: 	}
116: 
117: 	if err := s.signFunc(
118: 		ro,
119: 		ko,
120: 		signOptions,
121: 		[]string{refImage}); err != nil {
122: 		return errors.Errorf("unable to sign image with %s: %v", cosignKeyFile, err)
123: 	}
124: 
125: 	return nil
126: }
