128: func (s *ImageSigner) SignBuilder(
129: 	ctx context.Context,
130: 	imageReference string,
131: 	cosignSecrets []corev1.Secret,
132: 	builderKeychain authn.Keychain,
133: ) ([]v1alpha2.CosignSignature, error) {
134: 	const Timeout = time.Second * 30
135: 
136: 	signaturePaths := make([]v1alpha2.CosignSignature, 0)
137: 
138: 	for _, secret := range cosignSecrets {
139: 		keyRef := fmt.Sprintf("k8s://%s/%s", secret.Namespace, secret.Name)
140: 		keyOpts := options.KeyOpts{
141: 			KeyRef: keyRef,
142: 			PassFunc: func(bool) ([]byte, error) {
143: 				if password, ok := secret.Data[cosignutil.SecretDataCosignPassword]; ok {
144: 					return password, nil
145: 				}
146: 
147: 				return []byte(""), nil
148: 			},
149: 		}
150: 
151: 		if cosignRepository, ok := secret.Annotations[cosignutil.RepositoryAnnotationPrefix]; ok {
152: 			if err := os.Setenv(cosignutil.CosignRepositoryEnv, cosignRepository); err != nil {
153: 				return nil, fmt.Errorf("failed setting %s env variable: %w", cosignutil.CosignRepositoryEnv, err)
154: 			}
155: 		}
156: 
157: 		if cosignDockerMediaType, ok := secret.Annotations[cosignutil.DockerMediaTypesAnnotationPrefix]; ok {
158: 			if err := os.Setenv(cosignutil.CosignDockerMediaTypesEnv, cosignDockerMediaType); err != nil {
159: 				return nil, fmt.Errorf("failed setting %s env variable: %w", cosignutil.CosignDockerMediaTypesEnv, err)
160: 			}
161: 		}
162: 
163: 		registryOptions := options.RegistryOptions{KubernetesKeychain: true, Keychain: builderKeychain}
164: 
165: 		signOptions := options.SignOptions{
166: 			Registry:          registryOptions,
167: 			AnnotationOptions: options.AnnotationOptions{},
168: 			Upload:            true,
169: 			Recursive:         false,
170: 			TlogUpload:        false,
171: 		}
172: 
173: 		rootOptions := options.RootOptions{Timeout: Timeout}
174: 
175: 		if err := s.signFunc(
176: 			&rootOptions,
177: 			keyOpts,
178: 			signOptions,
179: 			[]string{imageReference}); err != nil {
180: 			return nil, fmt.Errorf("unable to sign image with specified key from secret %s in namespace %s: %w", secret.Name, secret.Namespace, err)
181: 		}
182: 
183: 		reference, err := name.ParseReference(imageReference)
184: 		if err != nil {
185: 			return nil, fmt.Errorf("failed to parse reference: %w", err)
186: 		}
187: 
188: 		registryOpts, err := registryOptions.ClientOpts(ctx)
189: 		if err != nil {
190: 			return nil, err
191: 		}
192: 
193: 		signatureTag, err := s.fetchSignatureFunc(reference, registryOpts...)
194: 		if err != nil {
195: 			return nil, err
196: 		}
197: 
198: 		image, err := remote.Image(signatureTag, remote.WithAuthFromKeychain(builderKeychain))
199: 		if err != nil {
200: 			return nil, err
201: 		}
202: 
203: 		digest, err := image.Digest()
204: 		if err != nil {
205: 			return nil, err
206: 		}
207: 
208: 		signaturePaths = append(
209: 			signaturePaths,
210: 			v1alpha2.CosignSignature{
211: 				SigningSecret: keyRef,
212: 				TargetDigest:  signatureTag.Digest(digest.String()).String(),
213: 			},
214: 		)
215: 
216: 		if _, found := os.LookupEnv(cosignutil.CosignDockerMediaTypesEnv); found {
217: 			err = os.Unsetenv(cosignutil.CosignDockerMediaTypesEnv)
218: 			if err != nil {
219: 				return nil, fmt.Errorf("failed to cleanup environment variable %s: %w", cosignutil.CosignDockerMediaTypesEnv, err)
220: 			}

221: 		}
222: 
223: 		if _, found := os.LookupEnv(cosignutil.CosignRepositoryEnv); found {
224: 			err = os.Unsetenv(cosignutil.CosignRepositoryEnv)
225: 			if err != nil {
226: 				return nil, fmt.Errorf("failed to cleanup environment variable %s: %w", cosignutil.CosignRepositoryEnv, err)
227: 			}
228: 		}
229: 	}
230: 
231: 	return signaturePaths, nil
232: }
