234: func FetchBuilderSigningSecrets(ctx context.Context, client k8sclient.Interface, namespace string, serviceAccountName string) ([]corev1.Secret, error) {
235: 	secretFetcher := &secret.Fetcher{Client: client}
236: 	serviceAccountSecrets, err := secretFetcher.SecretsForServiceAccount(ctx, serviceAccountName, namespace)
237: 	if err != nil {
238: 		return nil, fmt.Errorf("failed to retrieve secrets for ServiceAccount %s/%s: %w", namespace, serviceAccountName, err)
239: 	}
240: 
241: 	cosignSecrets := make([]corev1.Secret, 0)
242: 
243: 	for _, cosignSecret := range serviceAccountSecrets {
244: 		_, passwordOk := cosignSecret.Data[cosignutil.SecretDataCosignPassword]
245: 		_, keyOk := cosignSecret.Data[cosignutil.SecretDataCosignKey]
246: 
247: 		if passwordOk && keyOk {
248: 			cosignSecrets = append(cosignSecrets, *cosignSecret)
249: 		}
250: 	}
251: 
252: 	// successful
253: 	return cosignSecrets, nil
254: }
