256: func findCosignSecrets(secretLocation string) ([]string, error) {
257: 	var result []string
258: 
259: 	files, err := ioutil.ReadDir(secretLocation)
260: 	if err != nil {
261: 		return nil, err
262: 	}
263: 
264: 	for _, path := range files {
265: 		if path.IsDir() {
266: 			result = append(result, path.Name())
267: 		}
268: 	}
269: 
270: 	return result, nil
271: }

